from flask import (Blueprint, render_template, request, jsonify, session,                   redirect, url_for, flash, Response, send_from_directory, current_app)from datetime import datetime, date, timedeltaimport osimport jsonimport uuidimport pytzimport tracebackfrom .astrology.core.chart import calculate_chart_datafrom .astrology.core.calc_client import calc_clientfrom .astrology.core.planets import PLANET_COLORSfrom .astrology.predictions.data import HOUSE_INTERPRETATIONSfrom .astrology.panchang import calculate_panchangfrom .astrology.dasha import calculate_vimshottarifrom .astrology.predictions.engine import generate_evidence_based_predictionsfrom .astrology.predictions.daily import get_daily_forecastfrom .astrology.predictions.timeline_engines import timeline_predict_enginefrom .astrology.remedies.engine import get_personalized_remediesfrom .astrology.store import save_chart, list_charts, get_chart, delete_chartfrom .api.external import geocode_place, get_ip_locationmain = Blueprint("main", __name__)def _enrich_chart_for_template(chart: dict):    """Add legacy keys to chart dict for template compatibility."""    if not chart: return    from .astrology.core.planets import NAKSHATRA_NAMES, NAK_SPAN, PLANET_COLORS    R_NAMES = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya",               "Tula","Vrishchika","Dhanu","Makara","Kumbha","Meena"]    asc_lon = chart.get("ascendant", 0)    asc_rashi = int(asc_lon // 30)    chart["lagna"] = {        "rashi": asc_rashi, "rashi_name": R_NAMES[asc_rashi],        "nakshatra": {"name": NAKSHATRA_NAMES[int(asc_lon / NAK_SPAN) % 27]}    }    chart["house_occupants"] = {i: [] for i in range(1, 13)}    for p, data in chart["planets"].items():        data["name"] = p        data["retrograde"] = data.get("is_retrograde", False)        data["color"] = PLANET_COLORS.get(p, "#fff")        data["rashi_name"] = R_NAMES[data["rashi"]]        h = data.get("house", (data["rashi"] - asc_rashi + 12) % 12 + 1)        chart["house_occupants"][h].append(p)def _load_active_chart():    """Helper to load chart from session or most recent in vault."""    try:        # 1. Try to load by explicit active_chart_id        cid = session.get("active_chart_id")        if cid:            chart_data = get_chart(cid)            # Robust check for required birth data (V3.22)            if chart_data and (chart_data.get("birth_dob") or chart_data.get("dob")):                _enrich_chart_for_template(chart_data)                dob = chart_data.get('birth_dob') or chart_data.get('dob')                tob = chart_data.get('birth_tob') or chart_data.get('tob') or "12:00"                lat = chart_data.get('latitude') or chart_data.get('lat') or 28.6                lon = chart_data.get('longitude_coord') or chart_data.get('lon') or 77.2                tz = chart_data.get('timezone') or chart_data.get('tz') or "Asia/Kolkata"                birth_dt = datetime.strptime(f"{dob} {tob}", "%Y-%m-%d %H:%M")                chart_obj = calculate_chart_data(birth_dt, float(lat), float(lon), tz)                return chart_data, chart_obj            else:                # Session stale or chart missing data                session.pop("active_chart_id", None)        # 2. Fallback to birth_dob/tob in session        dob = session.get("birth_dob")        tob = session.get("birth_tob")        conf = session.get("birth_time_conf", "HIGH")        if dob and tob:            lat, lon = session.get("birth_lat", 28.6), session.get("birth_lon", 77.2)            tz_str = session.get("birth_tz", "Asia/Kolkata")            birth_dt = datetime.strptime(f"{dob} {tob}", "%Y-%m-%d %H:%M")            chart_obj = calculate_chart_data(birth_dt, float(lat), float(lon), tz_str, birth_time_conf=conf)            chart = chart_obj.model_dump()            chart["id"] = "session-temp"            _enrich_chart_for_template(chart)            return chart, chart_obj    except Exception as e:        if "CALCULATION_UNAVAILABLE" in str(e):             raise e        current_app.logger.error(f"Failed to load chart: {e}")        # Clean up bad session state to avoid loops        session.pop("active_chart_id", None)        session["skip_autoload"] = True    return None, None@main.route("/")def index():    if request.args.get("vault") == "1" or request.args.get("action") == "new":        session["skip_autoload"] = True        session.pop("active_chart_id", None)    # Phase 4: V3.22 Premium Landing Logic    # If no profile is active, but charts exist in the vault, auto-load the latest.    if not session.get("active_chart_id") and not session.get("skip_autoload"):        saved = list_charts()        user_charts = [c for c in saved if not str(c.get('id', '')).startswith(('bt-', 'test-', 'h-test-'))]        if user_charts:            latest = user_charts[0]            cid = latest["id"]            chart_data = get_chart(cid)            # Only auto-load if it has birth data to avoid redirect loops            if chart_data and chart_data.get("birth_dob"):                session.update({                    "active_chart_id": cid,                    "birth_name": chart_data.get("name"),                    "birth_dob": chart_data.get("birth_dob"),                    "birth_tob": chart_data.get("birth_tob"),                    "birth_lat": chart_data.get("latitude"),                    "birth_lon": chart_data.get("longitude_coord"),                    "birth_tz": chart_data.get("timezone")                })                return redirect(url_for("main.dashboard"))    if session.get("active_chart_id") and not request.args.get("vault") and not request.args.get("action"):        return redirect(url_for("main.dashboard"))    saved_charts = list_charts()    ip_loc = get_ip_location()    return render_template("index.html", ip_loc=ip_loc, saved_charts=saved_charts)@main.route("/kundli", methods=["GET", "POST"])def kundli():    if request.method == "GET" and not session.get("active_chart_id"):        return redirect(url_for("main.index", action="new"))    if not calc_client.check_health():        return render_template("error.html", code="CALCULATION_SERVICE_OFFLINE",                               message="The deterministic calculation engine is currently offline. Please ensure Docker is running.")    error = None    chart, chart_obj = None, None    if request.method == "POST":        try:            name = request.form.get("name", "Native")            dob, tob = request.form.get("dob"), request.form.get("tob")            conf = request.form.get("confidence", "HIGH")            place = request.form.get("place", "")            lat, lon = request.form.get("lat"), request.form.get("lon")            tz_str = request.form.get("timezone", "Asia/Kolkata")            if not dob or not tob: raise ValueError("Birth date and time are mandatory.")            if not lat or not lon:                geo = geocode_place(place or "New Delhi")                if "error" in geo: raise ValueError(geo["error"])                lat, lon, tz_str = geo["lat"], geo["lon"], geo["timezone"]            session.update({"birth_lat": float(lat), "birth_lon": float(lon), "birth_tz": tz_str,                            "birth_name": name, "birth_dob": dob, "birth_tob": tob, "birth_time_conf": conf})            birth_dt = datetime.strptime(f"{dob} {tob}", "%Y-%m-%d %H:%M")            chart_obj = calculate_chart_data(birth_dt, float(lat), float(lon), tz_str, birth_time_conf=conf)            chart = chart_obj.model_dump()            chart["name"] = name # Ensure name is passed to save_chart (V3.15)            chart["id"] = save_chart(chart)            session["active_chart_id"] = chart["id"]            _enrich_chart_for_template(chart)            if request.headers.get('X-Requested-With') == 'XMLHttpRequest':                return jsonify({"ok": True, "redirect": url_for("main.dashboard")})            return redirect(url_for("main.dashboard"))        except Exception as e:            error = str(e)            if request.headers.get('X-Requested-With') == 'XMLHttpRequest':                return jsonify({"ok": False, "error": error}), 400    if not chart: chart, chart_obj = _load_active_chart()    return render_template("kundli.html", chart=chart, error=error)@main.route("/api/v1/debug/dashboard-data")def api_debug_dashboard_data():    """Debug route for V3.22 Data Binding validation."""    try:        chart, chart_obj = _load_active_chart()        if not chart_obj: return jsonify({"error": "NO_ACTIVE_CHART"}), 400        preds = generate_evidence_based_predictions(chart_obj)        daily = get_daily_forecast(chart_obj, datetime.now())        domain_scores = {p['domain']: p['score'] for p in preds['predictions']}        return jsonify({            "profile_name": session.get("birth_name"),            "active_chart_id": session.get("active_chart_id"),            "current_dasha": daily.get("current_dasha"),            "domain_scores": domain_scores,            "top_signal": preds['predictions'][0] if preds['predictions'] else None        })    except Exception as e:        import traceback        traceback.print_exc()        return jsonify({"error": str(e)}), 500@main.route("/dashboard")def dashboard():    try:        chart, chart_obj = _load_active_chart()        if not chart_obj:            return render_template("dashboard.html", no_profile=True, preds=None, daily=None, timeline=None, chart=None, current_age=0)        try:            preds = generate_evidence_based_predictions(chart_obj)        except Exception as pred_err:            current_app.logger.error(f"Prediction engine synthesis error: {pred_err}")            preds = {"predictions": [], "upcoming_roadmap": []}        try:            daily = get_daily_forecast(chart_obj, datetime.now())        except Exception as daily_err:            current_app.logger.error(f"Daily forecast error: {daily_err}")            daily = {"current_dasha": "Deterministic Scan"}        # 2. V3.22 Intelligence Roadmap (High-level scan with fallback)        timeline_obj = None        try:            from .astrology.predictions.v322_timeline import lifetime_timeline_engine_v22            timeline_obj = lifetime_timeline_engine_v22.generate_lifetime_timeline(chart_obj, chart["id"])        except Exception as tl_err:            current_app.logger.error(f"Timeline generation error: {tl_err}")            timeline_obj = type('obj', (object,), {'events': [], 'phases': []})        current_age = round((datetime.now() - chart_obj.birth_datetime).days / 365.2425, 1)        return render_template("dashboard.html",                               preds=preds,                               daily=daily,                               timeline=timeline_obj,                               current_age=current_age,                               chart=chart)    except Exception as e:        import traceback        traceback.print_exc()        current_app.logger.error(f"Dashboard Critical Error: {e}")        flash(f"Notice: Dashboard loaded with safe fallback context ({str(e)}).", "warning")        return render_template("dashboard.html",                               preds={"predictions": [], "upcoming_roadmap": []},                               daily={"current_dasha": "Deterministic Scan"},                               timeline=type('obj', (object,), {'events': [], 'phases': []}),                               current_age=30,                               chart=chart if 'chart' in locals() and chart else {"name": session.get("birth_name", "Native")})    except RuntimeError as e:        if "CALCULATION_UNAVAILABLE" in str(e):             return render_template("error.html", code="CALCULATION_SERVICE_OFFLINE",                                   message="The deterministic calculation engine is currently offline. Please ensure Docker is running.")        raise e@main.route("/predictions")def predictions():    chart, chart_obj = _load_active_chart()    if not chart_obj: return redirect(url_for("main.index"))    preds = generate_evidence_based_predictions(chart_obj)    remedies = get_personalized_remedies(chart_obj)    from .astrology.store import save_prediction_snapshot    # Beta Context (V3.15)    source_type = "REAL_WORLD" if session.get("is_beta_session") else "UNVERIFIED"    p_id = session.get("beta_participant_id")    s_id = session.get("beta_session_id")    g_id = session.get("beta_group_id", "BETA_GROUP_1")    for p in preds.get("predictions", []):        try:            save_prediction_snapshot(chart["id"], p, source_type=source_type,                                     participant_id=p_id, session_id=s_id, group_id=g_id)        except Exception as e:            current_app.logger.error(f"Snapshot failed: {e}")    yearly = timeline_predict_engine.get_year_ahead(chart_obj, date.today().year)    return render_template("predictions.html",                           preds=preds,                           remedies=remedies,                           yearly=yearly,                           chart=chart)@main.route("/kundli/load/<cid>")def load_kundli(cid):    # Clear any potential redirect loop block    session.pop("skip_autoload", None)    # Security/Separation: Prevent normal users from loading backtest data    if str(cid).startswith(('bt-', 'test-', 'h-test-')) and not session.get('is_admin'):        flash("Unauthorized access to restricted data.", "danger")        return redirect(url_for("main.index"))    chart_data = get_chart(cid)    if not chart_data:        flash("Chart not found.", "danger")        return redirect(url_for("main.index"))    session.update({        "active_chart_id": cid,        "birth_name": chart_data.get("name"),        "birth_dob": chart_data.get("birth_dob"),        "birth_tob": chart_data.get("birth_tob"),        "birth_lat": chart_data.get("latitude"),        "birth_lon": chart_data.get("longitude_coord"),        "birth_tz": chart_data.get("timezone"),        "birth_time_conf": chart_data.get("birth_time_confidence", "HIGH")    })    next_page = request.args.get("next")    if next_page == "predictions":        return redirect(url_for("main.predictions"))    if next_page == "dashboard":        return redirect(url_for("main.dashboard"))    return redirect(url_for("main.kundli"))@main.route("/kundli/delete/<cid>", methods=["POST"])def delete_kundli(cid):    if delete_chart(cid):        return jsonify({"ok": True})    return jsonify({"ok": False, "error": "Could not delete"}), 400@main.route("/api/sky")def api_sky():    lat = float(request.args.get("lat", 28.6))    lon = float(request.args.get("lon", 77.2))    tz_str = request.args.get("tz", "Asia/Kolkata")    import pytz    tz = pytz.timezone(tz_str)    now_local = datetime.now(tz)    # Search from start of the local day to ensure we get today's sunrise    midnight_local = now_local.replace(hour=0, minute=0, second=0, microsecond=0)    from .astrology.core.datetime import datetime_to_jd    jd = datetime_to_jd(midnight_local.replace(tzinfo=None), tz_str)    from .astrology.panchang.sky import get_sunrise, get_sunset, get_rahu_kaal    sr = get_sunrise(jd, lat, lon)    ss = get_sunset(jd, lat, lon)    def format_jd(j):        if not j: return "--:--"        from .astrology.core.datetime import jd_to_datetime        return pytz.utc.localize(jd_to_datetime(j)).astimezone(tz).strftime("%H:%M")    return jsonify({        "sunrise": format_jd(sr),        "sunset": format_jd(ss),        "rahu_kaal": get_rahu_kaal(datetime.now().weekday(), sr, ss, tz_str)    })@main.route("/api/geocode")def api_geocode():    q = request.args.get("q", "")    return jsonify(geocode_place(q))@main.route("/api/transit/heatmap")def api_transit_heatmap():    lat = float(request.args.get("lat", 28.6))    lon = float(request.args.get("lon", 77.2))    tz_str = request.args.get("tz", "Asia/Kolkata")    # Simple intensity logic for demo purposes (Phase 11/12 Integration)    months = ["SEP","OCT","NOV","DEC","JAN","FEB","MAR","APR","MAY","JUN","JUL","AUG"]    results = []    import random    start_dt = date.today()    for i in range(12):        curr = start_dt + timedelta(days=i*30)        results.append({            "month": months[i % 12],            "date": curr.isoformat(),            "score": random.randint(40, 85) # Deterministic scores could be calculated if needed        })    return jsonify(results)@main.route("/history")def history():    chart_id = session.get("active_chart_id")    if not chart_id:        flash("Please generate or load a chart to view history.", "info")        return redirect(url_for("main.index"))    # Production Cleanup: Show only REAL_WORLD or UNVERIFIED records for this user.    # Exclude explicitly synthetic test cohorts unless in admin/beta mode.    outcomes = PredictionOutcome.query.filter_by(chart_id=chart_id)\        .filter(PredictionOutcome.source_type.in_(["REAL_WORLD", "UNVERIFIED"]))\        .order_by(PredictionOutcome.created_at.desc()).all()    return render_template("history.html", outcomes=outcomes)@main.route("/showcase")def showcase():    """    Dedicated Showcase Mode for Meeting Demonstrations.    Presents Past (Validation), Present (Active), and Future (Prospective).    """    # 1. Load Historical Showcase Cases    cases_path = os.path.join(current_app.root_path, '..', 'data', 'backtest', 'raw', 'historical_cases.json')    with open(cases_path, 'r') as f:        all_cases = json.load(f)    # Selection for Demo (High Reliability)    demo_names = ["Steve Jobs", "Princess Diana", "Bill Gates"]    demo_cases = [c for c in all_cases if c['name'] in demo_names]    # 2. Present Situation (Using current user or default if none)    chart, chart_obj = _load_active_chart()    current_intel = None    if chart_obj:        preds = generate_evidence_based_predictions(chart_obj)        current_intel = {            "top_signals": [p for p in preds['predictions'] if p['prediction_strength'] in ['PEAK', 'ACTIVE']][:3],            "timeline": preds.get('timeline', [])[:5]        }    return render_template("showcase.html", demo_cases=demo_cases, current_intel=current_intel)@main.route("/showcase/replay/<name>/<event_idx>")def showcase_replay(name, event_idx):    """    Executes a 'Historical Replay' - calculating predictions BEFORE a known event.    """    cases_path = os.path.join(current_app.root_path, '..', 'data', 'backtest', 'raw', 'historical_cases.json')    with open(cases_path, 'r') as f:        all_cases = json.load(f)    case = next((c for c in all_cases if c['name'] == name), None)    if not case: return "Case not found", 404    event = case['events'][int(event_idx)]    event_date = datetime.strptime(event['date'], "%Y-%m-%d")    # HISTORICAL CUTOFF: 30 days before the event    cutoff_date = event_date - timedelta(days=30)    # Calculate Chart    birth_dt = datetime.strptime(f"{case['dob']} {case['tob']}", "%Y-%m-%d %H:%M")    chart_obj = calculate_chart_data(birth_dt, case['lat'], case['lon'], case['tz'])    # Run Engine at Cutoff    preds = generate_evidence_based_predictions(chart_obj, selected_date=cutoff_date)    # Find relevant prediction    target_pred = next((p for p in preds['predictions'] if p['domain'] == event['domain']), None)    # Optional: Persist Showcase Snapshot for Auditability    from .astrology.store import save_prediction_snapshot    save_prediction_snapshot(f"demo-{name.lower().replace(' ', '-')}", target_pred, source_type="SHOWCASE")    return render_template("showcase_detail.html",                           case=case, event=event,                           cutoff=cutoff_date.strftime("%Y-%m-%d"),                           prediction=target_pred,                           all_preds=preds['predictions'])@main.route("/report/download")def download_complete_report():    """Consolidated PDF Report (Phase 15/28/V3.16)."""    chart, chart_obj = _load_active_chart()    if not chart_obj: return redirect(url_for("main.index"))    # 1. Present Predictions    preds = generate_evidence_based_predictions(chart_obj)    # 1.5 Dasha (V3.22)    from .astrology.dasha.vimshottari import get_vimshottari_periods    dashas = get_vimshottari_periods(chart_obj.planets["Moon"].longitude, chart_obj.birth_datetime)    # 2. V3.22 Lifetime Timeline (Optimized: Check DB first)    from .database.models import TimelineEventSnapshot    from .astrology.predictions.v322_timeline import lifetime_timeline_engine_v22    existing_events = TimelineEventSnapshot.query.filter_by(chart_id=chart["id"]).all()    if existing_events:        timeline = type('obj', (object,), {'events': existing_events, 'phases': []})    else:        timeline = lifetime_timeline_engine_v22.generate_lifetime_timeline(chart_obj, chart["id"])    # 3. Historical Replay Data (Steve Jobs 1980 proof)    # ... existing implementation ...    cases_path = os.path.join(current_app.root_path, '..', 'data', 'backtest', 'raw', 'historical_cases.json')    demo_cases_results = []    try:        with open(cases_path, 'r') as f:            all_cases = json.load(f)        # We only replay a subset for the report to keep it focused        demo_names = ["Steve Jobs"]        for name in demo_names:            case = next((c for c in all_cases if c['name'] == name), None)            if case:                event = case['events'][0] # Career breakthrough                event_date = datetime.strptime(event['date'], "%Y-%m-%d")                cutoff_date = event_date - timedelta(days=30)                birth_dt = datetime.strptime(f"{case['dob']} {case['tob']}", "%Y-%m-%d %H:%M")                c_obj = calculate_chart_data(birth_dt, case['lat'], case['lon'], case['tz'])                p_output = generate_evidence_based_predictions(c_obj, selected_date=cutoff_date)                target_p = next((p for p in p_output['predictions'] if p['domain'] == event['domain']), None)                demo_cases_results.append({                    "case_name": name,                    "event": event['description'],                    "actual_date": event['date'],                    "cutoff_date": cutoff_date.strftime("%Y-%m-%d"),                    "prediction": target_p                })    except Exception as e:        current_app.logger.error(f"Failed to load demo cases for report: {e}")    # 4. Consolidate data for PDF    from .astrology.predictions.accuracy_engine import accuracy_engine    accuracy_data = {        "real_world": accuracy_engine.get_cohort_metrics("REAL_WORLD"),        "historical": accuracy_engine.get_cohort_metrics("HISTORICAL"),        "calibration": accuracy_engine.get_calibration_data()    }    data = {        "profile": {            "name": session.get("birth_name"),            "dob": session.get("birth_dob"),            "tob": session.get("birth_tob"),            "place": session.get("birth_place"),            "lat": session.get("birth_lat"),            "lon": session.get("birth_lon"),            "tz": session.get("birth_tz")        },        "present": {            "as_of": datetime.now().strftime("%Y-%m-%d %H:%M"),            "top_signals": [p for p in preds['predictions'] if p['prediction_strength'] in ['PEAK', 'ACTIVE']][:3],            "predictions": preds['predictions'],            "timeline": preds.get('timeline', [])        },        "lifecycle": {            "events": [e.model_dump() if hasattr(e, 'model_dump') else e for e in timeline.events],            "phases": []        },        "clusters": preds.get('clusters', []),        "past_validation": demo_cases_results,        "accuracy": accuracy_data,        "dashas": [d.model_dump() if hasattr(d, 'model_dump') else d for d in dashas],        "metadata": {            "engine": "V3.22 Premium",            "calculation": "CALC-SWE-2.10.3",            "ayanamsa": "Lahiri",            "baseline_precision": "60.7%",            "baseline_recall": "43.6%"        }    }    from .utils.pdf_generator import generate_complete_pdf    pdf_bytes = generate_complete_pdf(data)    return Response(pdf_bytes, mimetype="application/pdf",                    headers={"Content-Disposition": f"attachment;filename=Jyotish_Intelligence_Report_{data['profile']['name']}.pdf"})@main.route("/kundli/pdf")def kundli_pdf():    # Placeholder or specific Kundli PDF if required. Redirecting to full report for now.    return redirect(url_for("main.download_complete_report"))@main.route("/api/v1/user/settings", methods=["POST"])def update_settings():    data = request.json    if "expert_mode" in data:        session["expert_mode"] = bool(data["expert_mode"])    if data.get("admin_key") == "astro-predictions-2026": # Session security for meeting        session["is_admin"] = True    return jsonify({"success": True, "expert_mode": session.get("expert_mode", False)})@main.route("/api/v1/outcome/update", methods=["POST"])def update_prediction_outcome():    """V3.22 Life Event Verification: Updates outcome for an immutable prediction snapshot."""    from .database.models import db, PredictionOutcome    data = request.json    snapshot = db.session.get(PredictionOutcome, data.get("id"))    if not snapshot: return jsonify({"success": False, "error": "NOT_FOUND"}), 404    # Validation Integrity (Phase 1/3)    actual_date_str = data.get("actual_date")    if not actual_date_str:         return jsonify({"success": False, "error": "Actual event date is required."}), 400    actual_dt = datetime.strptime(actual_date_str, "%Y-%m-%d")    # Prospective Enforcement (Only for REAL_WORLD)    if snapshot.source_type == "REAL_WORLD" and actual_dt.date() < snapshot.created_at.date():         return jsonify({"success": False, "error": "RETROSPECTIVE_OUTCOME_REJECTED"}), 400    snapshot.status = data.get("status", "OCCURRED")    snapshot.actual_event_date = actual_date_str    snapshot.user_notes = data.get("notes")    snapshot.verification_level = data.get("verification_level", "SELF_REPORTED")    snapshot.reported_at = datetime.utcnow()    # Deterministic Matching    peak_dt = datetime.strptime(snapshot.peak_date, "%Y-%m-%d")    snapshot.timing_error_days = (actual_dt - peak_dt).days    snapshot.matching_version = "EVENT-MATCH-V1"    db.session.commit()    return jsonify({"success": True, "status": snapshot.status, "error_days": snapshot.timing_error_days})@main.route("/api/v1/predict/explain/<domain>")def api_explain_prediction(domain):    chart, chart_obj = _load_active_chart()    if not chart_obj: return jsonify({"error": "NO_ACTIVE_CHART"}), 400    preds = generate_evidence_based_predictions(chart_obj)    domain_pred = next((p for p in preds["predictions"] if domain.lower() in p["domain"].lower()), None)    if not domain_pred: return jsonify({"error": "DOMAIN_NOT_FOUND"}), 404    return jsonify({        "facts": [],        "explanation": {            "why": domain_pred.get("evidence_chain", []),            "practicalGuidance": domain_pred.get("practical_guidance", [])        }    })@main.route("/api/chat", methods=["POST"])def api_chat():    msg = request.json.get("message", "")    return jsonify({"response": f"The planets indicate your query about '{msg}' is significant. Please consult the life predictions for detailed evidence."})@main.route("/prashna", methods=["GET", "POST"])def prashna():    from .astrology.prashna.engine import analyze_prashna    from .astrology.panchang import calculate_panchang    result = None    chart = None    if request.method == "POST":        try:            q_type = request.form.get("question_type")            # Prashna is for the moment and current user location            lat, lon = session.get("birth_lat", 28.6), session.get("birth_lon", 77.2)            tz_str = session.get("birth_tz", "Asia/Kolkata")            now = datetime.now()            chart_obj = calculate_chart_data(now, lat, lon, tz_str)            # Get current panchang for micro-timing            p_res = calculate_panchang(now.date(), lat, lon, tz_str)            result = analyze_prashna(chart_obj, q_type, panchang=p_res)            chart = chart_obj.model_dump()            _enrich_chart_for_template(chart)        except Exception as e:            flash(f"Prashna error: {e}", "danger")    return render_template("prashna.html", result=result, chart=chart)@main.route("/panchang", methods=["GET", "POST"])def panchang():    from .astrology.panchang import calculate_panchang    # Default inputs    target_date = date.today()    lat, lon = session.get("birth_lat", 28.6), session.get("birth_lon", 77.2)    place = "New Delhi"    tz_str = session.get("birth_tz", "Asia/Kolkata")    if request.method == "POST":        try:            date_str = request.form.get("date")            if date_str: target_date = datetime.strptime(date_str, "%Y-%m-%d").date()            p_lat = request.form.get("lat")            p_lon = request.form.get("lon")            if p_lat and p_lon:                lat, lon = float(p_lat), float(p_lon)                place = request.form.get("place", "Custom Location")                tz_str = request.form.get("timezone", "Asia/Kolkata")        except Exception as e:            flash(f"Sync error: {e}", "danger")    res = calculate_panchang(target_date, lat, lon, tz_str)    return render_template("panchang.html", panchang=res, sky=res["sky"], place=place, today=date.today().isoformat())@main.route("/matchmaking", methods=["GET", "POST"])def matchmaking():    from .astrology.matchmaking.engine import get_matchmaking_score    result = None    error = None    if request.method == "POST":        try:            # Simple wrapper to get chart for boy/girl            def get_m_chart(prefix):                name = request.form.get(f"{prefix}_name")                dob = request.form.get(f"{prefix}_dob")                tob = request.form.get(f"{prefix}_tob")                place = request.form.get(f"{prefix}_place")                geo = geocode_place(place)                if "error" in geo: raise ValueError(f"Location error for {name}: {geo['error']}")                dt = datetime.strptime(f"{dob} {tob}", "%Y-%m-%d %H:%M")                return calculate_chart_data(dt, geo["lat"], geo["lon"], geo["timezone"])            b_chart = get_m_chart("b")            g_chart = get_m_chart("g")            result = get_matchmaking_score(b_chart, g_chart)        except Exception as e:            error = str(e)    return render_template("matchmaking.html", result=result, error=error)@main.route("/varshaphala")def varshaphala():    from .astrology.core.varshaphala import get_varshaphala_data, get_solar_return_jd    from .astrology.dasha.mudda import calculate_mudda_dasha    from .astrology.core.tajika_varsheshwar import calculate_varsheshwar    from .astrology.core.datetime import jd_to_datetime    chart, chart_obj = _load_active_chart()    if not chart_obj: return redirect(url_for("main.index"))    target_year = date.today().year    # 1. Solar Return JD    from .astrology.core.datetime import datetime_to_jd    natal_jd = datetime_to_jd(chart_obj.birth_datetime, "UTC")    sr_jd = get_solar_return_jd(natal_jd, target_year)    sr_dt = jd_to_datetime(sr_jd)    # 2. Calculate SR Chart    sr_chart_obj = calculate_chart_data(sr_dt, chart_obj.latitude, chart_obj.longitude, chart_obj.timezone)    sr_chart = sr_chart_obj.model_dump()    _enrich_chart_for_template(sr_chart)    # 3. Tajika Metrics    v_data = get_varshaphala_data(chart_obj.birth_datetime, chart_obj.asc_rashi, target_year)    # 4. Varsheshwar    is_day = sr_chart_obj.planets["Sun"].house in [7, 8, 9, 10, 11, 12]    varsheshwar = calculate_varsheshwar(sr_chart_obj.planets, sr_chart_obj.asc_rashi,                                       v_data["muntha_rashi"], chart_obj.asc_rashi, is_day)    # 5. Mudda Dasha    mudda = calculate_mudda_dasha(sr_chart_obj.planets["Moon"].longitude, sr_dt)    # Combine for template    sr_chart.update(v_data)    sr_chart["varsheshwar"] = varsheshwar    return render_template("varshaphala.html", yearly=sr_chart, mudda=mudda, chart=chart)@main.route("/transit")def transit():    from .astrology.transit.engine import calculate_transit    from .astrology.core.planets import NAKSHATRA_NAMES, NAKSHATRA_LORDS, PLANET_COLORS    chart, natal_obj = _load_active_chart()    date_str = request.args.get("date")    if date_str:        try:            target_dt = datetime.strptime(date_str, "%Y-%m-%d")            # Preserve current time for accuracy            now = datetime.now()            target_dt = target_dt.replace(hour=now.hour, minute=now.minute)        except:            target_dt = datetime.now()    else:        target_dt = datetime.now()    # User location or birth location    lat = session.get("birth_lat", 28.6)    lon = session.get("birth_lon", 77.2)    tz_str = session.get("birth_tz", "Asia/Kolkata")    t_chart_obj = calculate_transit(target_dt, float(lat), float(lon), tz_str)    t_chart = t_chart_obj.model_dump()    _enrich_chart_for_template(t_chart)    # Calculate Nakshatra/House Map    nak_house_map = []    R_NAMES = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrishchika","Dhanu","Makara","Kumbha","Meena"]    for p_name, p_data in t_chart["planets"].items():        # Map to natal house if natal available        natal_h = None        warning = "secondary"        if natal_obj:            # Transit rashi relative to natal lagna            natal_h = (p_data["rashi"] - natal_obj.asc_rashi + 12) % 12 + 1            if natal_h in [6, 8, 12]: warning = "warning"            if natal_h in [1, 5, 9, 10]: warning = "positive"            if p_name in ["Saturn", "Rahu", "Mars"] and natal_h in [1, 4, 7, 8, 12]: warning = "danger"        nak_house_map.append({            "planet": p_name,            "color": PLANET_COLORS.get(p_name, "#fff"),            "rashi": R_NAMES[p_data["rashi"]],            "dms": f"{int(p_data['longitude']%30)}° {int((p_data['longitude']%1)*60)}'",            "nakshatra": p_data["nakshatra"]["name"],            "nak_lord": p_data["nakshatra"]["lord"],            "natal_house": natal_h,            "warning_level": warning,            "retrograde": p_data.get("is_retrograde", False)        })    return render_template("transit.html", transit=t_chart, natal=chart,                           nak_house_map=nak_house_map,                           selected_date=target_dt.strftime("%Y-%m-%d"), tz_str=tz_str)@main.route("/timeline")def timeline():    """V3.22 Lifecycle Intelligence - Life Event Mapping & Validation."""    chart, chart_obj = _load_active_chart()    if not chart_obj: return redirect(url_for("main.index"))    from .astrology.predictions.v322_timeline import lifetime_timeline_engine_v22    # Generate Timeline (V3.22)    tl_obj = lifetime_timeline_engine_v22.generate_lifetime_timeline(chart_obj, chart["id"])    # Save snapshots for verification (Use V3.17 base helper for persistence)    from .astrology.predictions.v317_timeline import lifetime_timeline_engine_v17    lifetime_timeline_engine_v17.save_timeline_events(chart["id"], tl_obj.events)    # 3. Clustering (V3.21+)    from .astrology.predictions.clustering import clustering_engine    clusters = clustering_engine.cluster_predictions([e.model_dump() for e in tl_obj.events])    current_age = round((datetime.now() - chart_obj.birth_datetime).days / 365.2425, 1)    return render_template("timeline.html",                           timeline=tl_obj,                           phases=tl_obj.phases,                           clusters=clusters,                           current_age=current_age,                           chart=chart)@main.route("/api/v1/timeline/verify/<event_id>", methods=["POST"])def verify_timeline_event(event_id):    """Walk-forward validation: Matches actual event against prediction."""    from .database.models import db, TimelineEventSnapshot    data = request.json    actual_date_str = data.get("actual_date")    if not actual_date_str:        return jsonify({"success": False, "error": "MISSING_DATE"}), 400    snapshot = TimelineEventSnapshot.query.get_or_404(event_id)    # Phase 3: Prospective Enforcement    actual_dt = datetime.strptime(actual_date_str, "%Y-%m-%d")    prediction_dt = snapshot.created_at    if snapshot.status == "FUTURE_FORECAST" and actual_dt.date() < prediction_dt.date():        snapshot.status = "REJECTED_RETROSPECTIVE"        snapshot.integrity_reason = "RETROSPECTIVE_OUTCOME"        db.session.commit()        return jsonify({"success": False, "error": "RETROSPECTIVE_OUTCOME_REJECTED"}), 400    snapshot.actual_event_date = actual_date_str    snapshot.matching_version = "EVENT-MATCH-V1"    # Deterministic Matching (V3.17/V3.20)    try:        peak_dt = datetime.strptime(snapshot.peak_date, "%Y-%m-%d")        start_dt = datetime.strptime(snapshot.start_date, "%Y-%m-%d")        end_dt = datetime.strptime(snapshot.end_date, "%Y-%m-%d")        error = (actual_dt - peak_dt).days        snapshot.timing_error_days = error        if start_dt <= actual_dt <= end_dt:            if abs(error) <= 7:                snapshot.matching_status = "MATCH"            else:                snapshot.matching_status = "PARTIAL_MATCH"        else:            snapshot.matching_status = "NO_MATCH"        db.session.commit()        return jsonify({            "success": True,            "status": snapshot.matching_status,            "error_days": error        })    except Exception as e:        return jsonify({"success": False, "error": str(e)}), 500@main.route("/admin/accuracy")def admin_accuracy():    """V3.22 Internal Accuracy, Calibration & Hardening Dashboard."""    from .astrology.predictions.accuracy_engine import accuracy_engine    real_world = accuracy_engine.get_detailed_cohort_metrics("REAL_WORLD")    historical = accuracy_engine.get_detailed_cohort_metrics("HISTORICAL")    simulated = accuracy_engine.get_detailed_cohort_metrics("SIMULATED")    calibration = accuracy_engine.get_calibration_data("REAL_WORLD")    evidence = accuracy_engine.analyze_evidence_patterns()    optimal = accuracy_engine.get_optimal_horizons()    return render_template("admin_accuracy.html",                           real_world=real_world,                           historical=historical,                           simulated=simulated,                           calibration=calibration,                           evidence=evidence,                           optimal=optimal)@main.route("/beta/enroll", methods=["POST"])def beta_enroll():    """    Enrolls a participant into the Controlled Beta (V3.15).    """    data = request.json    p_id = data.get("participant_id")    if not p_id:        return jsonify({"success": False, "error": "MISSING_PARTICIPANT_ID"}), 400    session["is_beta_session"] = True    session["beta_participant_id"] = p_id    session["beta_session_id"] = str(uuid.uuid4())[:8]    session["beta_group_id"] = data.get("group_id", "BETA_GROUP_1")    return jsonify({        "success": True,        "participant_id": p_id,        "session_id": session["beta_session_id"]    })@main.route("/beta/exit", methods=["POST"])def beta_exit():    """Exits the beta session mode."""    session.pop("is_beta_session", None)    session.pop("beta_participant_id", None)    session.pop("beta_session_id", None)    return jsonify({"success": True})@main.route("/admin/quality")def admin_quality():    """Requirement 10: Admin-only dashboard."""    return render_template("admin_quality.html")